import{_ as t,o as e,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"CDS Squid: NVMe-oF-Gateway","description":"","frontmatter":{"title":"CDS Squid: NVMe-oF-Gateway","date":"2023-07-25T00:00:00.000Z","updated":"2023-07-26T00:00:00.000Z","tags":["Ceph","NVMe","oF","Gateway","High Availability","Scalability"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/CDS_Squid_-_NVMe-oF-Gateway.md","filePath":"posts/2023/CDS_Squid_-_NVMe-oF-Gateway.md","lastUpdated":1780459816000}'),r={name:"posts/2023/CDS_Squid_-_NVMe-oF-Gateway.md"};function i(n,a,s,h,d,g){return e(),l("div",null,[...a[0]||(a[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-gateway-的高可用性和可扩展性讨论" tabindex="-1">会议主题：Ceph Gateway 的高可用性和可扩展性讨论 <a class="header-anchor" href="#会议主题-ceph-gateway-的高可用性和可扩展性讨论" aria-label="Permalink to &quot;会议主题：Ceph Gateway 的高可用性和可扩展性讨论&quot;">​</a></h4><h4 id="与会人员-ceph-研发团队成员" tabindex="-1">与会人员：Ceph 研发团队成员 <a class="header-anchor" href="#与会人员-ceph-研发团队成员" aria-label="Permalink to &quot;与会人员：Ceph 研发团队成员&quot;">​</a></h4><h4 id="会议时间-具体时间未提供" tabindex="-1">会议时间：具体时间未提供 <a class="header-anchor" href="#会议时间-具体时间未提供" aria-label="Permalink to &quot;会议时间：具体时间未提供&quot;">​</a></h4><h4 id="会议地点-线上会议" tabindex="-1">会议地点：线上会议 <a class="header-anchor" href="#会议地点-线上会议" aria-label="Permalink to &quot;会议地点：线上会议&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>高可用性和可扩展性</strong></p><ul><li><strong>讨论内容</strong>：团队讨论了如何使用 Getter Groups 来实现 RBD 卷的高可用性和可扩展性，目标是允许从不同的 gateway 访问相同的 RBD 卷。</li><li><strong>关键问题</strong>：如何进行负载均衡，即如何决定哪个 gateway 服务于哪个卷。</li><li><strong>决定事项</strong>：初步决定不自动进行负载均衡，而是通过 Gateway CLI 允许用户指定哪个 gateway 是某个卷的首选。未来可能会考虑自动化。</li></ul></li><li><p><strong>多路径和 Ana 支持</strong></p><ul><li><strong>讨论内容</strong>：讨论了当前的多路径和 Ana 支持配置，以及用户如何配置这些设置。</li><li><strong>关键问题</strong>：如何设置和优化路径状态，以及如何在配置文件中持久化这些设置。</li><li><strong>决定事项</strong>：决定在未来的版本中允许用户通过 RPC 配置路径状态，但初始版本可能只支持一个优化路径。</li></ul></li><li><p><strong>故障转移和恢复</strong></p><ul><li><strong>讨论内容</strong>：讨论了在没有 IP 故障转移的情况下，如何处理故障转移和恢复的问题。</li><li><strong>关键问题</strong>：如何确保在故障转移时，客户端能够正确地重新连接到新的路径。</li><li><strong>决定事项</strong>：需要进一步测试和验证，可能需要通过发现服务或类似机制来处理路径的移除和重新添加。</li></ul></li><li><p><strong>并发 gRPC 处理</strong></p><ul><li><strong>讨论内容</strong>：由于时间限制，该议题被推迟到下一次会议讨论。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li><strong>负载均衡</strong>：继续研究如何实现更智能的负载均衡机制。</li><li><strong>多路径和 Ana 支持</strong>：完善配置选项，允许用户更灵活地配置路径状态。</li><li><strong>故障转移和恢复</strong>：进行更多的测试，确保在各种故障情况下客户端能够正确地重新连接。</li><li><strong>并发 gRPC 处理</strong>：在下一次会议中深入讨论并发 gRPC 处理的细节。</li></ul><h4 id="其他备注" tabindex="-1">其他备注： <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注：&quot;">​</a></h4><ul><li>会议中还提到了关于 Gateway groups 的其他问题，如如何报告不可访问的命名空间等，这些问题将在未来讨论。</li><li>对于网络流量的问题，会议确认了在 Ceph 架构中，前端和后端的网络流量不需要成倍增加，因为复制发生在后端。</li></ul><h4 id="会议结束语" tabindex="-1">会议结束语： <a class="header-anchor" href="#会议结束语" aria-label="Permalink to &quot;会议结束语：&quot;">​</a></h4><p>感谢所有与会者的参与，下一次会议将继续讨论未完成的技术议题。</p>',13)])])}const c=t(r,[["render",i]]);export{p as __pageData,c as default};
